<script setup>
import { computed, reactive, ref, watch, nextTick, onBeforeUnmount, onMounted } from 'vue';
import { createApi, filterRecords, statusTone } from './api.js';

const props = defineProps({ apiBase: { type: String, default: '/api' }, tokenProvider: { type: Function, default: null } });
const emit = defineEmits(['record-change', 'workspace-error']);
const state = reactive({ user: null, users: [], records: [], templates: [], permissions: {} });
const busy = ref(false), error = ref(''), notice = ref(''), view = ref('workspace'), scope = ref('all'), query = ref(''), status = ref(''), selectedId = ref(null), tab = ref('overview');
const modalElement = ref(null);
let returnFocus = null;
const dialog = ref(null), actionData = reactive({}), draft = reactive({}), form = reactive({}), searchResult = ref(null), preview = ref(null), historySnapshot = ref(null);
const comment = ref(''), attachmentSection = ref('Continuation'), ldsResult = ref(null), permissionUser = ref('remote'), permissionForm = reactive({ crossSite: 'none', dualSign: false });
const steps = ['Unassigned', 'In Process', 'Awaiting Approval', 'ESR Issued', 'ESR Closed'];
const current = computed(() => state.records.find(r => r.id === selectedId.value));
const record = computed(() => historySnapshot.value || current.value);
const local = computed(() => record.value?.site === state.user?.site);
const delegated = computed(() => state.permissions[state.user?.id]?.dualSign);
const editable = computed(() => !historySnapshot.value && local.value && record.value?.status === 'In Process' && (record.value.engineerId === state.user?.id || state.user?.role === 'Supervisor'));
const canAttach = computed(() => editable.value || (!historySnapshot.value && local.value && record.value?.status === 'Unassigned' && (record.value.requestorId === state.user?.id || state.user?.role === 'Supervisor')));
const canComment = computed(() => !historySnapshot.value && (local.value || state.permissions[state.user?.id]?.crossSite === 'review'));
const filtered = computed(() => filterRecords(state.records, query.value, status.value, scope.value, state.user?.id));
const counts = computed(() => Object.fromEntries(steps.map(s => [s, state.records.filter(r => r.status === s || (s === 'ESR Issued' && r.status.startsWith('ESR Issued'))).length])));
const initials = name => (name || '').split(' ').map(n => n[0]).slice(0, 2).join('');
const date = value => new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
const time = value => new Date(value).toLocaleString();
const owner = id => state.users.find(u => u.id === id)?.name || 'Not assigned';
const api = (path, data, binary) => createApi(props.apiBase, props.tokenProvider)(path, data, binary);

async function run(fn) {
  if (busy.value) return;
  busy.value = true; error.value = '';
  try { await fn(); } catch (e) { error.value = e.message; emit('workspace-error', { message: e.message }); }
  finally { busy.value = false; }
}
watch(dialog, async (value, old) => {
  if (value) { if (!old) returnFocus = document.activeElement?.shadowRoot?.activeElement || document.activeElement; await nextTick(); modalElement.value?.querySelector('input:not([type=checkbox]), select, textarea, button')?.focus(); }
  else returnFocus?.focus();
});
function trapFocus(event) {
  if (event.key !== 'Tab') return;
  const items = [...modalElement.value.querySelectorAll('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href]')].filter(e => e.getClientRects().length);
  const active = modalElement.value.getRootNode().activeElement;
  if (event.shiftKey && active === items[0]) { event.preventDefault(); items.at(-1)?.focus(); }
  else if (!event.shiftKey && active === items.at(-1)) { event.preventDefault(); items[0]?.focus(); }
}
function handleEscape(event) { if (event.key === 'Escape' && dialog.value) { event.preventDefault(); closeDialog(); } }
onMounted(() => document.addEventListener('keydown', handleEscape));
onBeforeUnmount(() => { closePreview(); document.removeEventListener('keydown', handleEscape); });
async function reload() {
  const data = await api('/bootstrap'); Object.assign(state, data);
  if (view.value === 'admin' && state.user.role !== 'Administrator') navigate('workspace');
  if (selectedId.value && !current.value) { selectedId.value = null; view.value = 'workspace'; }
  if (current.value) resetDraft();
}
watch(() => props.tokenProvider, async value => { if (value) await run(async () => { historySnapshot.value = null; dialog.value = null; await reload(); }); }, { immediate: true });
function resetDraft() {
  const r = current.value;
  if (r) Object.assign(draft, { resolution: r.resolution, rationale: r.rationale, dfs: r.dfs, dfsReference: r.dfsReference, tvd: r.tvd, tvdReference: r.tvdReference, attributes: [...r.attributes] });
}
function openRecord(r) { selectedId.value = r.id; view.value = 'record'; tab.value = 'overview'; historySnapshot.value = null; searchResult.value = null; error.value = ''; notice.value = ''; resetDraft(); }
function navigate(target, nextScope = 'all') { view.value = target; scope.value = nextScope; selectedId.value = null; status.value = ''; query.value = ''; historySnapshot.value = null; error.value = ''; notice.value = ''; }
function newRequest() {
  Object.assign(form, { title: '', jcn: '', noJcn: false, name: state.user.name, shop: state.user.shop, phone: state.user.phone, references: '', condition: '' });
  ldsResult.value = null; dialog.value = 'create'; error.value = '';
}
async function createRequest() {
  await run(async () => {
    const r = await api('/records', { ...form, jcn: form.noJcn ? 'N/A' : form.jcn });
    await reload(); dialog.value = null; openRecord(r); notice.value = 'Request submitted. Attach supporting files in the Files tab.'; emit('record-change', { id: r.id, action: 'create', status: r.status });
  });
}
async function mutate(action, data = {}) {
  const result = await api(`/records/${current.value.id}/${action}`, { ...data, version: current.value.version });
  emit('record-change', { id: selectedId.value, action, status: result.status });
  await reload(); notice.value = 'Changes saved.'; return result;
}
async function saveDraft() { await run(async () => { await mutate('draft', { ...draft }); }); }
function action(name) {
  error.value = ''; dialog.value = name;
  for (const key of Object.keys(actionData)) delete actionData[key];
  Object.assign(actionData, { engineerId: 'engineer', comment: '', reason: '', condition: record.value?.condition, status: 'Completed', explanation: '', shop: state.user.shop, acknowledgeDeferred: false });
}
async function confirmAction() {
  await run(async () => { const name = dialog.value; await mutate(name, { ...actionData }); dialog.value = null; if (name === 'delete') navigate('workspace'); });
}
async function findHistory() { await run(async () => { searchResult.value = await api('/history/search', { condition: record.value.condition }); }); }
async function copyMatch(match) {
  await run(async () => { await navigator.clipboard.writeText(`Resolution\n${match.resolution}\n\nRationale\n${match.rationale}`); notice.value = 'Resolution and rationale copied to clipboard.'; });
}
function useMatch(match) { draft.resolution = match.resolution; draft.rationale = match.rationale; notice.value = 'Historical text inserted. Review and save the draft before signing.'; }
function applyTemplate(template) { draft.resolution += `${draft.resolution ? '\n\n' : ''}${template.resolution}`; draft.rationale += `${draft.rationale ? '\n\n' : ''}${template.rationale}`; dialog.value = null; notice.value = 'Approved template inserted. Review and save your draft.'; }
async function postComment() { await run(async () => { await mutate('comment', { text: comment.value }); comment.value = ''; }); }
async function upload(event) {
  const file = event.target.files?.[0]; if (!file) return;
  await run(async () => {
    if (file.size > 15 * 1024 * 1024) throw new Error('File must be 15 MB or smaller.');
    const base64 = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result.split(',')[1]); reader.onerror = () => reject(Error('Unable to read file.')); reader.readAsDataURL(file); });
    await mutate('attach', { name: file.name, type: file.type || (file.name.endsWith('.txt') ? 'text/plain' : ''), base64, section: attachmentSection.value });
  }); event.target.value = '';
}
async function downloadPdf() {
  await run(async () => { const suffix = historySnapshot.value ? `?revision=${historySnapshot.value.revision}` : ''; const blob = await api(`/records/${current.value.id}/pdf${suffix}`, undefined, true); saveBlob(blob, `ESR-${record.value.serial}.pdf`); });
}
function saveBlob(blob, name) { const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = name; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
async function previewFile(file) {
  await run(async () => {
    const suffix = historySnapshot.value ? `?revision=${historySnapshot.value.revision}` : '';
    const blob = await api(`/records/${current.value.id}/files/${file.id}${suffix}`, undefined, true);
    closePreview(); preview.value = { name: file.name, type: file.type, url: URL.createObjectURL(blob), blob }; dialog.value = 'preview';
  });
}
function closePreview() { if (preview.value) URL.revokeObjectURL(preview.value.url); preview.value = null; }
function closeDialog() { dialog.value = null; closePreview(); error.value = ''; }
watch(permissionUser, id => Object.assign(permissionForm, state.permissions[id] || { crossSite: 'none', dualSign: false }));
async function savePermission() { await run(async () => { await api('/permissions', { userId: permissionUser.value, ...permissionForm }); await reload(); notice.value = 'Permissions updated.'; }); }
const dialogTitle = computed(() => ({ assign: 'Assign an engineer', reject: 'Return request to shop', resubmit: 'Resubmit request', delete: 'Delete unassigned request', resolve: 'Sign · Resolved By', approve: 'Sign · Approved By', return: 'Request changes', complete: 'Shop execution · Blocks 25 / 26', close: 'Division review & closeout', revise: 'Create a new revision' })[dialog.value]);
</script>

<template>
  <div class="app" :aria-busy="busy">
    <aside class="sidebar" :inert="!!dialog">
      <a class="brand" href="#" @click.prevent="navigate('workspace')"><span class="brand-mark">E<span>↗</span></span><span>ESR<span class="brand-sub">ENGINEERING WORKSPACE</span></span></a>
      <div class="facility"><span class="facility-icon">⌖</span><div><strong>TRF {{ state.user?.site || 'Bangor' }}</strong><span>Engineering services</span></div><span class="live-dot"></span></div>
      <div class="nav-label">WORKSPACE</div>
      <nav aria-label="Primary navigation">
        <button :class="{ active: view === 'workspace' && scope === 'all' || view === 'record' }" @click="navigate('workspace')"><span>▦</span> All requests <small>{{ state.records.length }}</small></button>
        <button :class="{ active: scope === 'mine' && view === 'workspace' }" @click="navigate('workspace', 'mine')"><span>◉</span> My work</button>
        <button :class="{ active: scope === 'history' && view === 'workspace' }" @click="navigate('workspace', 'history')"><span>◷</span> Historical ESRs</button>
        <button :class="{ active: view === 'templates' }" @click="navigate('templates')"><span>▤</span> Template library</button>
        <button v-if="state.user?.role === 'Administrator'" :class="{ active: view === 'admin' }" @click="navigate('admin')"><span>⚙</span> Permissions</button>
      </nav>
      <div class="sidebar-note"><span class="small-icon">↗</span><strong>One request. Full traceability.</strong><p>From the deckplate to engineering approval and closeout.</p><span class="small-tag">DIGITAL WORKFLOW</span></div>
      <div class="profile"><span class="avatar">{{ initials(state.user?.name) }}</span><div><strong>{{ state.user?.name || 'Waiting for session' }}</strong><span>{{ state.user?.role || 'Connect your host identity' }}</span></div></div>
    </aside>
    <div class="main-shell" :inert="!!dialog">
      <header class="topbar"><div>Engineering <span>/</span> {{ view === 'record' ? record?.serial || 'New request' : view === 'templates' ? 'Template library' : view === 'admin' ? 'Permissions' : 'Service requests' }}</div><div class="topbar-right"><span class="live-dot"></span> {{ state.user?.site || 'TRF' }} workspace <button class="icon-button" aria-label="Refresh workspace" :disabled="busy" @click="run(reload)">↻</button></div></header>
      <main>
        <div v-if="error && !dialog" class="alert error" role="alert">{{ error }} <button @click="error = ''" aria-label="Dismiss error">×</button></div>
        <div v-if="notice" class="alert success" role="status">{{ notice }} <button @click="notice = ''" aria-label="Dismiss notice">×</button></div>
        <div v-if="!state.user" class="empty"><div class="empty-icon">▦</div><h1>Engineering service requests</h1><p>{{ props.tokenProvider ? 'Connecting to the workspace…' : 'Provide a tokenProvider to connect the component to your API.' }}</p></div>
        <template v-else-if="view === 'workspace'">
          <div class="page-heading"><div><div class="eyebrow">ENGINEERING OPERATIONS</div><h1>{{ scope === 'history' ? 'Historical ESRs' : scope === 'mine' ? 'My work' : 'Service requests' }}<span class="heading-dot">.</span></h1><p>{{ scope === 'history' ? 'Find prior resolutions and explore the complete engineering record.' : 'A clear path from finding to resolution.' }}</p></div><button v-if="['Requestor', 'Shop', 'Engineer', 'Supervisor'].includes(state.user.role)" class="primary" @click="newRequest"><span>＋</span> New request</button></div>
          <section class="stats" aria-label="Workflow counts"><button v-for="(step, i) in steps" :key="step" :class="['stat', { selected: status === step }]" @click="status = status === step ? '' : step"><span class="stat-label"><span :class="['status-dot', statusTone(step)]"></span>{{ step }}</span><strong>{{ counts[step] }}</strong><span class="stat-foot">{{ ['Ready for assignment', 'Engineering in progress', 'Ready for technical review', 'Released to the shop', 'Work fully dispositioned'][i] }} <span>↗</span></span></button></section>
          <section v-if="scope !== 'history'" class="focus-banner"><div class="focus-symbol">⌁</div><div><span class="eyebrow">KEEP WORK MOVING</span><h2>{{ counts['Awaiting Approval'] ? `${counts['Awaiting Approval']} request${counts['Awaiting Approval'] === 1 ? '' : 's'} ready for technical review` : 'Every detail, in one engineering record' }}</h2><p>Review the resolution, verify references, and sign with confidence.</p></div><button class="text-button" @click="status = 'Awaiting Approval'">View approval queue <span>→</span></button></section>
          <section class="card workspace-card"><div class="table-title"><div><h2>{{ scope === 'history' ? 'Resolved engineering records' : scope === 'mine' ? 'Assigned to you & your requests' : 'Request workspace' }}</h2><span>{{ filtered.length }} records <span class="muted">· Live demo data</span></span></div><span class="small-tag">{{ state.user.site.toUpperCase() }}</span></div><div class="filters"><label class="search"><span>⌕</span><input v-model="query" aria-label="Search requests" placeholder="Search serial, title, JCN, or attribute…"><kbd>⌕</kbd></label><select v-model="status" aria-label="Filter by status"><option value="">All statuses</option><option v-for="step in [...steps.slice(0, 4), 'ESR Issued – Deferred', 'ESR Closed']" :key="step">{{ step }}</option></select><button v-if="status || query" class="text-button" @click="status = ''; query = ''">Clear</button></div>
            <div class="table-scroll"><table><thead><tr><th>REQUEST / SERIAL</th><th>STATUS</th><th>ENGINEER</th><th>ATTRIBUTES</th><th>UPDATED</th><th><span class="sr-only">Open</span></th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><button class="record-link" @click="openRecord(r)"><span class="serial">{{ r.serial || 'PENDING ASSIGNMENT' }} <span v-if="r.revision">· REV {{ r.serial.slice(6) }}</span></span><strong>{{ r.title }}</strong><span class="muted">{{ r.jcn }} <span v-if="r.rejected">· Returned to requestor</span></span></button></td><td><span :class="['badge', statusTone(r.status)]"><span class="status-dot"></span>{{ r.status }}</span></td><td><div v-if="r.engineerId" class="person"><span class="avatar mini">{{ initials(owner(r.engineerId)) }}</span><span>{{ owner(r.engineerId) }}</span></div><span v-else class="muted">— Unassigned</span></td><td><div class="tags"><span v-if="r.dfs === 'yes'" class="tag special">DFS</span><span v-if="r.tvd === 'yes'" class="tag special">TVD</span><span v-for="a in r.attributes" :key="a" class="tag">{{ a }}</span><span v-if="!r.attributes.length && r.dfs !== 'yes' && r.tvd !== 'yes'" class="muted">—</span></div></td><td class="nowrap muted">{{ date(r.updatedAt) }}</td><td><button class="icon-button" :aria-label="`Open ${r.title}`" @click="openRecord(r)">→</button></td></tr></tbody></table></div><div v-if="!filtered.length" class="empty"><h3>No requests found</h3><p>Adjust your filters or create a new request.</p></div><footer class="table-footer"><span>Showing {{ filtered.length }} of {{ state.records.length }} accessible requests</span><span><span class="live-dot"></span> All changes are recorded</span></footer>
          </section>
          <div class="workspace-footer"><span>TRIDENT REFIT FACILITY <span> / </span> ENGINEERING SERVICES</span><span>Synthetic demonstration · v0.1</span></div>
        </template>
        <template v-else-if="view === 'record' && record">
          <button class="back-link" @click="navigate('workspace')">← Back to requests</button>
          <div class="page-heading detail-heading"><div><div class="eyebrow">{{ record.serial || 'AWAITING SERIAL NUMBER' }} <span v-if="record.revision">· REVISION {{ record.serial.slice(6) }}</span></div><h1>{{ record.title }}</h1><div class="detail-meta"><span :class="['badge', statusTone(record.status)]">{{ record.status }}</span><span>{{ record.site }} · Shop {{ record.shop }}</span><span v-for="a in [...record.attributes, ...(record.dfs === 'yes' ? ['DFS'] : []), ...(record.tvd === 'yes' ? ['TVD'] : [])]" :key="a" class="tag">{{ a }}</span></div></div><div class="action-row"><button v-if="record.signatures.some(s => s.block === 'Approved By')" @click="downloadPdf" :disabled="busy">↓ Export PDF</button><button v-if="!historySnapshot && local && ['Engineer', 'Supervisor'].includes(state.user.role) && (record.status.startsWith('ESR Issued') || record.status === 'ESR Closed')" @click="action('revise')">↗ New revision</button></div></div>
          <div v-if="historySnapshot" class="alert info">Viewing immutable revision {{ historySnapshot.serial }}. <button @click="historySnapshot = null; resetDraft()">Return to current revision →</button></div>
          <div v-if="!local" class="alert info">Cross-facility {{ state.permissions[state.user.id]?.crossSite === 'review' ? 'review access — comments are enabled' : 'read-only access' }}.</div>
          <div v-if="record.rejected" class="alert error">Returned to the requestor. See the review comments before resubmitting.</div>
          <div class="stepper" aria-label="Workflow progress"><div v-for="(step, i) in steps" :key="step" :class="{ done: i < steps.indexOf(record.status.startsWith('ESR Issued') ? 'ESR Issued' : record.status), current: step === (record.status.startsWith('ESR Issued') ? 'ESR Issued' : record.status) }"><span>{{ i + 1 }}</span><strong>{{ step }}</strong></div></div>
          <div class="tabs" role="tablist" aria-label="Record sections"><button v-for="t in ['overview', 'resolution', 'files', 'history', 'activity']" :key="t" role="tab" :aria-selected="tab === t" :class="{ active: tab === t }" @click="tab = t">{{ t === 'files' ? `Files (${record.attachments.length})` : t === 'history' ? `Revisions (${current.revisions.length})` : t[0].toUpperCase() + t.slice(1) }}</button></div>
          <div class="detail-grid">
            <section class="detail-content">
              <template v-if="tab === 'overview'">
                <div class="card padded"><div class="section-heading"><h2>Condition & finding</h2><span class="small-tag">REQUEST DETAILS</span></div><p class="prose">{{ record.condition }}</p><div class="fields-grid read-fields"><div><span>REQUESTOR</span><strong>{{ record.name }}</strong></div><div><span>SHOP / CODE</span><strong>{{ record.shop }}</strong></div><div><span>CONTACT</span><strong>{{ record.phone }}</strong></div><div><span>SUBMITTED</span><strong>{{ date(record.createdAt) }}</strong></div></div></div>
                <div class="card padded"><h2>Equipment & work context</h2><div class="fields-grid read-fields"><div><span>JOB CONTROL NUMBER</span><strong>{{ record.jcn }}</strong></div><div><span>REFIT</span><strong>{{ record.refit || 'Not provided' }}</strong></div><div><span>COMPONENT / TSN</span><strong>{{ record.component || 'Not provided' }}</strong></div><div><span>LOCATION</span><strong>{{ record.location || 'Not provided' }}</strong></div></div><label class="read-label">WORK STATEMENT</label><p>{{ record.workStatement || 'No LDS work statement linked.' }}</p><label class="read-label">REFERENCES</label><p class="prose">{{ record.references }}</p></div>
                <div v-if="record.revisionReason" class="card padded"><h2>Reason for revision</h2><p class="prose">{{ record.revisionReason }}</p></div>
                <div v-if="record.completion" class="card padded"><h2>Shop completion · Blocks 25 / 26</h2><p><span class="badge green">{{ record.completion.status }}</span> {{ record.completion.name }} · {{ record.completion.shop }} · {{ record.completion.date }}</p><p class="prose">{{ record.completion.explanation || 'Work completed as directed.' }}</p></div>
              </template>
              <template v-if="tab === 'resolution'">
                <div v-if="editable" class="ai-panel"><div><span class="eyebrow">ASSISTED RESOLUTION</span><h2>A useful starting point, grounded in history.</h2><p>Summarize this finding and find similar closed ESRs.</p></div><button :disabled="busy" @click="findHistory">✧ Summarize & search</button><small>Synthetic similarity results. Engineer verification is always required.</small></div>
                <div v-if="searchResult" class="card padded"><h2>Conceptual summary</h2><p>{{ searchResult.summary }}</p><h3>Similar resolved ESRs</h3><article v-for="match in searchResult.matches" :key="match.id" class="match"><div><span class="serial">{{ match.serial }}</span><h3>{{ match.title }}</h3><span class="badge green">{{ match.similarity }}% similarity</span></div><div class="action-row"><button @click="copyMatch(match)">Copy text</button><button class="primary small" @click="useMatch(match)">Use in draft</button></div></article><p v-if="!searchResult.matches.length">No historical matches are available.</p></div>
                <form class="card padded" @submit.prevent="saveDraft"><div class="section-heading"><div><h2>Engineering resolution</h2><p class="muted">{{ editable ? 'Prepare the technical direction and supporting rationale.' : 'Read-only engineering record' }}</p></div><button v-if="editable" type="button" @click="dialog = 'templates'">▤ Insert template</button></div><label>Resolution<textarea v-model="draft.resolution" v-if="editable" rows="10" placeholder="Document the steps required to resolve the finding…"></textarea><div v-else class="prose readonly-text">{{ record.resolution || 'Not yet drafted.' }}</div></label><label>Engineering rationale<textarea v-if="editable" v-model="draft.rationale" rows="5" placeholder="Explain the technical basis for this resolution…"></textarea><div v-else class="prose readonly-text">{{ record.rationale || 'Not yet drafted.' }}</div></label>
                  <div v-if="editable" class="reference-prompts"><h3>References & attributes</h3><label>1. DFS Required?<select v-model="draft.dfs" required><option value="">Select an answer</option><option value="no">No</option><option value="yes">Yes</option></select></label><label v-if="draft.dfs === 'yes'">DFS reference / document number<input v-model="draft.dfsReference" required></label><template v-if="draft.dfs"><label>2. TVD Required?<select v-model="draft.tvd" required><option value="">Select an answer</option><option value="no">No</option><option value="yes">Yes</option></select></label><label v-if="draft.tvd === 'yes'">TVD reference / document number<input v-model="draft.tvdReference" required></label></template><fieldset><legend>Applicable attributes</legend><label v-for="a in ['Level 1', 'Requires Rev', 'SOC', 'SUBSAFE']" :key="a" class="check"><input v-model="draft.attributes" type="checkbox" :value="a">{{ a }}</label></fieldset></div>
                  <div v-else class="fields-grid read-fields"><div><span>DFS REQUIRED</span><strong>{{ record.dfs || 'Not answered' }} {{ record.dfsReference }}</strong></div><div><span>TVD REQUIRED</span><strong>{{ record.tvd || 'Not answered' }} {{ record.tvdReference }}</strong></div></div>
                  <div v-if="editable" class="form-footer"><span class="muted">Save your changes before signing.</span><button class="primary" :disabled="busy">Save draft</button></div>
                </form>
              </template>
              <template v-if="tab === 'files'"><div class="card padded"><div class="section-heading"><div><h2>Supporting files</h2><p class="muted">Drawings, inspection photos, and continuation sheets.</p></div><span class="small-tag">{{ record.attachments.length }} / 20 FILES</span></div><div v-if="canAttach" class="upload-box"><span class="upload-icon">↑</span><h3>Add evidence to the engineering record</h3><p>PNG, JPEG, WebP, PDF or TXT · Original quality · Up to 15 MB each</p><div class="action-row"><label class="inline-label">Section<select v-model="attachmentSection"><option>Condition</option><option>Reference</option><option>Continuation</option></select></label><label class="button primary upload-button">Choose file<input type="file" aria-label="Upload supporting file" accept="image/png,image/jpeg,image/webp,application/pdf,text/plain" :disabled="busy" @change="upload"></label></div></div><div v-for="file in record.attachments" :key="file.id" class="file-row"><span class="file-icon">▤</span><div><strong>{{ file.name }}</strong><span>{{ file.section }} · {{ Math.ceil(file.size / 1024) }} KB · {{ file.uploadedBy }}</span></div><button @click="previewFile(file)" :disabled="busy">Preview</button></div><p v-if="!record.attachments.length" class="empty">No supporting files attached yet.</p></div></template>
              <template v-if="tab === 'history'"><div class="card padded"><h2>Revision history</h2><p class="muted">Prior issued versions are retained as immutable snapshots, including signatures and attachments.</p><article class="revision-row"><span class="revision-mark">{{ current.revision || '0' }}</span><div><h3>{{ current.serial }} <span class="badge blue">Current</span></h3><p>{{ current.revisionReason || 'Original engineering request' }}</p></div><button @click="historySnapshot = null; tab = 'overview'">View current</button></article><article v-for="revision in [...current.revisions].reverse()" :key="revision.revision" class="revision-row"><span class="revision-mark">{{ revision.revision }}</span><div><h3>{{ revision.serial }}</h3><p>{{ revision.revisionReason || 'Original issued version' }}</p><span class="muted">{{ revision.status }} · {{ date(revision.updatedAt) }}</span></div><button @click="historySnapshot = revision; tab = 'overview'">View snapshot</button></article><p v-if="!current.revisions.length" class="empty">No prior revisions. Issued versions are preserved when a new revision begins.</p></div></template>
              <template v-if="tab === 'activity'"><div class="card padded"><h2>Comments & review</h2><form v-if="canComment" @submit.prevent="postComment"><label class="sr-only" for="comment">Add a comment</label><textarea id="comment" v-model="comment" rows="3" placeholder="Add a comment to the engineering record…" required></textarea><div class="form-footer"><span class="muted">Recorded as {{ state.user.name }}</span><button class="primary" :disabled="busy">Post comment</button></div></form><article v-for="c in [...record.comments].reverse()" :key="c.id" class="comment"><span class="avatar mini">{{ initials(c.name) }}</span><div><strong>{{ c.name }}</strong><time>{{ time(c.time) }}</time><p class="prose">{{ c.text }}</p></div></article><p v-if="!record.comments.length" class="muted">No comments yet.</p></div><div class="card padded"><h2>Audit trail</h2><div v-for="entry in [...record.audit].reverse()" :key="entry.id" class="audit-entry"><span class="status-dot green"></span><div><strong>{{ entry.action }}</strong><p>{{ entry.actor }} · {{ time(entry.time) }}</p></div></div></div></template>
            </section>
            <aside class="record-aside"><div class="card padded"><span class="eyebrow">NEXT STEP</span><h2>{{ historySnapshot ? 'Historical snapshot' : record.status === 'Unassigned' ? 'Engineering assignment' : record.status === 'In Process' ? 'Prepare the resolution' : record.status === 'Awaiting Approval' ? 'Technical review' : record.status === 'ESR Closed' ? 'Record closed' : record.completion ? 'Division review' : 'Shop execution' }}</h2><p class="muted">Assigned engineer</p><div class="person"><span class="avatar">{{ initials(owner(record.engineerId)) }}</span><strong>{{ owner(record.engineerId) }}</strong></div><div v-if="!historySnapshot && local" class="workflow-actions">
              <template v-if="record.status === 'Unassigned' && state.user.role === 'Supervisor'"><button class="primary" @click="action('assign')">Assign engineer →</button><button @click="action('reject')">Return to shop</button><button class="danger-text" @click="action('delete')">Delete request</button></template>
              <button v-if="record.status === 'Unassigned' && record.rejected && record.requestorId === state.user.id" class="primary" @click="action('resubmit')">Update & resubmit</button>
              <button v-if="record.status === 'In Process' && (record.engineerId === state.user.id || delegated)" class="primary" @click="action('resolve')">Sign & submit for approval</button>
              <template v-if="record.status === 'Awaiting Approval' && (state.user.role === 'Supervisor' || delegated)"><button class="primary" @click="action('approve')">Approve & issue ESR</button><button v-if="state.user.role === 'Supervisor'" @click="action('return')">Request changes</button></template>
              <button v-if="record.status === 'ESR Issued' && !record.completion && state.user.role === 'Shop'" class="primary" @click="action('complete')">Record shop completion</button>
              <button v-if="record.status.startsWith('ESR Issued') && record.completion && state.user.role === 'Division Head'" class="primary" @click="action('close')">Review & close ESR</button>
            </div><p class="footnote">Actions are available to the responsible role. Use the demo identity selector to explore each handoff.</p></div><div class="card padded"><h2>Signature record</h2><div v-for="block in ['Resolved By', 'Approved By', 'Shop Representative', 'Division Head']" :key="block" class="signature"><span :class="['signature-icon', { signed: record.signatures.some(s => s.block === block) }]">{{ record.signatures.some(s => s.block === block) ? '✓' : '○' }}</span><div><strong>{{ block }}</strong><template v-if="record.signatures.find(s => s.block === block)"><span>{{ record.signatures.find(s => s.block === block).name }}</span><small>{{ time(record.signatures.find(s => s.block === block).time) }}</small></template><span v-else>Awaiting signature</span></div></div><p class="footnote">Demo signatures are bound to the active JWT identity.</p></div></aside>
          </div>
        </template>
        <template v-else-if="view === 'templates'"><div class="page-heading"><div><div class="eyebrow">APPROVED BASELINES</div><h1>Template library<span class="heading-dot">.</span></h1><p>Consistent starting points for clear engineering direction.</p></div><span class="badge green">Supervisor-approved only</span></div><div class="template-grid"><article v-for="t in state.templates" :key="t.id" class="card padded template-card"><span class="template-symbol">▤</span><span class="small-tag">{{ t.category }}</span><h2>{{ t.title }}</h2><p class="prose">{{ t.resolution }}</p><details><summary>Engineering rationale</summary><p>{{ t.rationale }}</p></details><p class="footnote">Insert this template from an editable ESR resolution.</p></article></div></template>
        <template v-else-if="view === 'admin'"><div class="page-heading"><div><div class="eyebrow">ADMINISTRATION</div><h1>User permissions<span class="heading-dot">.</span></h1><p>Manage cross-facility visibility and signature delegation.</p></div></div><form class="card padded admin-form" @submit.prevent="savePermission"><h2>Access & delegation</h2><label>User<select v-model="permissionUser"><option v-for="u in state.users" :value="u.id" :key="u.id">{{ u.name }} · {{ u.site }} · {{ u.role }}</option></select></label><label>Access to the other TRF<select v-model="permissionForm.crossSite"><option value="none">No cross-facility access</option><option value="read">Read-only</option><option value="review">Review — read and comment</option></select></label><label class="check"><input v-model="permissionForm.dualSign" type="checkbox">May sign both engineering signature blocks</label><p class="muted">Delegated signatures require a comment. Cross-facility access never permits editing or signing the other facility’s records.</p><button class="primary" :disabled="busy">Save permissions</button><div v-if="state.permissions[permissionUser]?.updatedAt" class="footnote">Last changed by {{ state.permissions[permissionUser].updatedBy }} · {{ time(state.permissions[permissionUser].updatedAt) }}</div></form></template>
      </main>
    </div>
    <div v-if="dialog" class="modal-backdrop" @click.self="closeDialog" @keydown.esc="closeDialog">
      <section ref="modalElement" class="modal" @keydown="trapFocus" role="dialog" aria-modal="true" aria-labelledby="dialog-title" :class="{ wide: ['create', 'templates', 'preview'].includes(dialog) }">
        <div class="modal-heading"><div><div class="eyebrow">ENGINEERING SERVICE REQUEST</div><h2 id="dialog-title">{{ dialog === 'create' ? 'Start a new request' : dialog === 'templates' ? 'Approved engineering templates' : dialog === 'preview' ? preview?.name : dialogTitle }}</h2></div><button class="icon-button" aria-label="Close dialog" @click="closeDialog">×</button></div>
        <div v-if="error" class="alert error" role="alert">{{ error }}</div>
        <form v-if="dialog === 'create'" @submit.prevent="createRequest"><label>Request title<input v-model="form.title" required placeholder="A concise description of the engineering issue" autofocus maxlength="180"></label><div class="lds-box"><div class="section-heading"><h3>Link a work package</h3><span class="small-tag">MOCK LDS</span></div><label class="check"><input v-model="form.noJcn" type="checkbox" @change="ldsResult = null">JCN not applicable (N/A)</label><div v-if="!form.noJcn" class="input-action"><label>Job Control Number<input v-model="form.jcn" required placeholder="JCN-260184" @input="ldsResult = null"></label><button type="button" :disabled="busy || !form.jcn" @click="run(async () => { ldsResult = await api(`/lds?jcn=${encodeURIComponent(form.jcn)}`) })">Import LDS</button></div><small v-if="!form.noJcn">Demo JCNs: JCN-260184 · JCN-260207</small><div v-if="ldsResult" class="lds-result"><strong>{{ ldsResult.workStatement }}</strong><span>{{ ldsResult.refit }} · {{ ldsResult.component }}</span><span>{{ ldsResult.location }}</span></div></div><div class="fields-grid"><label>Name<input v-model="form.name" required></label><label>Shop / code<input v-model="form.shop" required></label><label>Phone number<input v-model="form.phone" required type="tel"></label></div><label>References<textarea v-model="form.references" rows="2" required placeholder="Reference numbers, drawings, or applicable procedures"></textarea></label><label>Condition / finding<textarea v-model="form.condition" rows="4" required placeholder="Describe the observed issue and the engineering support needed."></textarea></label><p class="footnote">Submit the request, then attach photos and documents in the Files tab.</p><div class="form-footer"><button type="button" @click="closeDialog">Cancel</button><button class="primary" :disabled="busy">Submit request →</button></div></form>
        <div v-else-if="dialog === 'templates'"><article v-for="t in state.templates" :key="t.id" class="template-choice"><span class="small-tag">{{ t.category }}</span><h3>{{ t.title }}</h3><p class="prose">{{ t.resolution }}</p><button class="primary" @click="applyTemplate(t)">Insert template</button></article></div>
        <div v-else-if="dialog === 'preview' && preview"><img v-if="preview.type.startsWith('image/')" :src="preview.url" :alt="preview.name" class="file-preview"><iframe v-else :src="preview.url" :title="preview.name" class="file-preview" sandbox></iframe><div class="form-footer"><span class="muted">Original uploaded file</span><button @click="saveBlob(preview.blob, preview.name)">Download original</button></div></div>
        <form v-else @submit.prevent="confirmAction">
          <div v-if="['resolve', 'approve', 'complete', 'close'].includes(dialog)" class="signing-identity"><span class="avatar">{{ initials(state.user.name) }}</span><div><strong>{{ state.user.name }}</strong><span>{{ state.user.role }} · Verified demo JWT identity</span></div></div>
          <label v-if="dialog === 'assign'">Primary engineer<select v-model="actionData.engineerId" required><option v-for="u in state.users.filter(u => u.role === 'Engineer' && u.site === record.site)" :key="u.id" :value="u.id">{{ u.name }}</option></select></label>
          <label v-if="dialog === 'revise'">Reason for revision<textarea v-model="actionData.reason" required rows="4" placeholder="Explain why the issued ESR needs to change."></textarea></label><p v-if="dialog === 'revise'" class="muted">The issued content, files, and signatures will be preserved in revision history. The new draft copies the prior content and requires fresh engineering signatures.</p>
          <label v-if="dialog === 'resubmit'">Updated condition / finding<textarea v-model="actionData.condition" required rows="5"></textarea></label>
          <p v-if="dialog === 'delete'">Delete this unassigned request and its attachments? This action cannot be undone.</p>
          <template v-if="dialog === 'complete'"><label>Completion status<select v-model="actionData.status"><option>Completed</option><option>Deferred</option><option>Other</option><option>Canceled</option></select></label><label>Shop / code<input v-model="actionData.shop" required></label><label>Block 26 explanation {{ actionData.status === 'Completed' ? '(optional)' : '(required)' }}<textarea v-model="actionData.explanation" :required="actionData.status !== 'Completed'" rows="4"></textarea></label><p class="muted">Name and completion date are recorded by the server from your identity and sign-off time.</p></template>
          <template v-if="dialog === 'close'"><div class="lds-box"><strong>Shop disposition: {{ record.completion.status }}</strong><p>{{ record.completion.explanation || 'Completed as directed.' }}</p></div><label v-if="record.completion.status === 'Deferred'" class="check"><input v-model="actionData.acknowledgeDeferred" type="checkbox" required>I acknowledge the deferred disposition and concur with closure.</label></template>
          <label v-if="['reject', 'return', 'resolve', 'approve', 'close'].includes(dialog)">{{ ['reject', 'return'].includes(dialog) || delegated ? 'Comment (required)' : 'Signature comment (optional)' }}<textarea v-model="actionData.comment" :required="['reject', 'return'].includes(dialog) || (delegated && ['resolve', 'approve'].includes(dialog))" rows="3"></textarea></label>
          <p v-if="dialog === 'resolve'" class="muted">Your saved resolution, rationale, DFS and TVD answers will be validated before the request moves to approval.</p><p v-if="dialog === 'approve'" class="muted">Approval locks the technical content and makes the issued PDF available to the shop.</p>
          <div class="form-footer"><button type="button" @click="closeDialog">Cancel</button><button :class="dialog === 'delete' ? 'danger' : 'primary'" :disabled="busy">{{ dialog === 'delete' ? 'Delete request' : ['resolve', 'approve', 'complete', 'close'].includes(dialog) ? 'Confirm & sign' : dialog === 'revise' ? 'Create revision' : 'Confirm' }}</button></div>
        </form>
      </section>
    </div>
  </div>
</template>

<style>
:host{--esr-accent:#196b57;--esr-bg:#f5f7f8;display:block;color:#223632;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:14px;line-height:1.5;color-scheme:light}*{box-sizing:border-box}button,input,select,textarea{font:inherit}button,.button{border:1px solid #d7dfdc;background:#fff;color:#30463f;border-radius:7px;padding:9px 14px;font-weight:550;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:8px;transition:background .15s,border-color .15s}button:hover,.button:hover{background:#f0f5f2;border-color:#a8bbb3}button:disabled{opacity:.5;cursor:wait}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #6baf9b;outline-offset:3px}a{color:inherit;text-decoration:none}button.primary,.button.primary{background:var(--esr-accent);color:#fff;border-color:var(--esr-accent);box-shadow:0 2px 3px #153b2210}button.primary:hover{background:#125440}button.danger{background:#a82d32;color:#fff;border-color:#a82d32}.danger-text{color:#a82d32}.text-button,.icon-button,.back-link{border-color:transparent;background:transparent;box-shadow:none}.text-button{color:var(--esr-accent)}.icon-button{padding:5px 9px;font-size:19px}.app{display:flex;min-height:calc(100vh - 47px);background:var(--esr-bg)}.sidebar{width:238px;flex-shrink:0;background:#fff;border-right:1px solid #e1e7e4;display:flex;flex-direction:column;padding:30px 18px 20px;position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:12px;padding:0 10px;font-size:27px;line-height:1.1;font-weight:750;letter-spacing:-1px}.brand-mark{background:#175e4c;color:white;width:41px;height:43px;display:flex;align-items:center;justify-content:center;border-radius:10px;font-size:26px;position:relative;font-weight:600}.brand-mark>span{font-size:15px;position:absolute;right:3px;top:1px;color:#b1d9cc}.brand-sub{display:block;font-size:7.5px;letter-spacing:1